const body = $json.body || $json;
const sender = body.sender || body.from || body.phone || '';
const messageText = (body.message || body.text || '').trim();

let status = 'Belum Konfirmasi';
const lowerMsg = messageText.toLowerCase();
if (lowerMsg.includes('hadir') && !lowerMsg.includes('tidak')) {
  status = 'Hadir';
} else if (lowerMsg.includes('tidak hadir') || lowerMsg.includes('tidak')) {
  status = 'Tidak Hadir';
}

// Normalisasi nomor WA
let cleanPhone = sender.replace(/[^0-9]/g, '');
if (cleanPhone.startsWith('0')) cleanPhone = '62' + cleanPhone.substring(1);
else if (cleanPhone.startsWith('8')) cleanPhone = '62' + cleanPhone;

return {
  json: {
    nomor_wa: cleanPhone,
    pesan_masuk: messageText,
    status_deteksi: status,
    waktu_diterima: new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' })
  }
};
